import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const m=JSON.parse('{"title":"MCP 工具","description":"Mobile Inspector development documentation · MCP 工具","frontmatter":{"title":"MCP 工具","description":"Mobile Inspector development documentation · MCP 工具"},"headers":[],"relativePath":"zh/reference/mcp.md","filePath":"zh/reference/mcp.md"}'),a={name:"zh/reference/mcp.md"};function c(n,e,s,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-工具" tabindex="-1">MCP 工具 <a class="header-anchor" href="#mcp-工具" aria-label="Permalink to &quot;MCP 工具&quot;">​</a></h1><p>五个只读 stdio 工具共用现有项目范围 collector。没有修改源码、执行 Shell、另选根目录、开启采集或修复客户端的工具。</p><table tabindex="0"><thead><tr><th>工具</th><th>读取范围</th></tr></thead><tbody><tr><td><code>list_sessions</code></td><td>绑定项目中的可用会话</td></tr><tr><td><code>get_request_trace</code></td><td>一个会话代次，可选单个请求</td></tr><tr><td><code>get_related_logs</code></td><td>会话、请求或事件日志范围</td></tr><tr><td><code>list_incidents</code></td><td>有界候选观察</td></tr><tr><td><code>get_incident</code></td><td>保留的单个事件与共享诊断状态</td></tr></tbody></table><h2 id="安全分页" tabindex="-1">安全分页 <a class="header-anchor" href="#安全分页" aria-label="Permalink to &quot;安全分页&quot;">​</a></h2><p>先列出会话，原样保留 <code>sessionId</code> 和 <code>instanceGeneration</code>。可选请求选择器收窄轨迹与日志。默认 50、最多 200 条，字节上限可能使实际条数更少。<code>nextCursor</code> 必须配合同一选择器、代次、范围和 limit，直到 null。游标绑定项目、记录、修订与初始高水位，过期、陈旧或非法时拒绝。</p><p>结果包含 schemaVersion、项目、代次、修订、items、nextCursor、complete 和 gaps。<code>complete: false</code> 不能当作完整轨迹。清除、撤销与到期会失效已有读取。默认只读摘要，正文每次读取都需当前会话授权；认证正文、凭据、二进制与音频仍排除。</p><p>协议往返、安装包和认证主机互通是不同证据层级，新工具不自动继承旧主机验收范围。接入见 <a href="./../integrations/codex">Codex</a>，观察语义见<a href="./incidents">事件</a>。</p>',7)])])}const h=t(a,[["render",c]]);export{m as __pageData,h as default};
